config.script:
// aniversario_atendimento — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Gatilho: alguém da equipe ABRE um atendimento (a tela do atendimento ou uma aba dela).
//   1. lê o atendimento aberto (para saber o paciente) e o cadastro do paciente (data de nascimento);
//   2. se HOJE (no fuso da clínica) é o aniversário do paciente, mostra a QUEM ABRIU:
//      - um SELO "Aniversário hoje" no cabeçalho (fica nas abas do atendimento, some ao sair dele);
//      - um CARTÃO no topo da lateral com a mensagem de parabéns pronta (texto do knob, com o 1º nome).
//        Os botões de copiar chegam numa versão futura da Central: por ora a mensagem vai só no texto.
//   3. não sendo o aniversário (ou faltando a data), sai limpo, sem peça na tela.
//
// 29/02: em ano que não é bissexto, o aniversário é comemorado em 28/02.
// Quem vê: só quem pode ler o atendimento E o cadastro completo do paciente (requer_permissoes) — o agente
// lê com o papel dele, então a peça exige as mesmas leituras de quem a vê.
// Sem dado pessoal fora da tela: o ref leva só ids opacos (paciente e quem abriu); o resumo, só flags.
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var cfg = config || {};
var ev = event || {};
var params = ev.params || {};
var usuario = ev.usuario || {};
var ROTA = '/atendimento/:id';
var REQUER = ['atendimento:read', 'cliente:read:full'];
var MSG_PADRAO = 'Feliz aniversário, {nome}! Toda a equipe deseja um dia muito especial para você.';

function txt(v) { return (v === undefined || v === null) ? '' : String(v).trim(); }
function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}
function knob(v, padrao) { var s = txt(v); return (!s || s.indexOf('{{') === 0) ? padrao : s; }
function offsetMin(s) {
  var m = /^([+-])(\d{2}):(\d{2})$/.exec(String(s));
  if (!m) return -180;
  var val = parseInt(m[2], 10) * 60 + parseInt(m[3], 10);
  return m[1] === '-' ? -val : val;
}
function pad(n) { return (n < 10 ? '0' : '') + n; }
function primeiroNome(nome) {
  var s = txt(nome);
  if (!s) return '';
  var i = s.indexOf(' ');
  return i > 0 ? s.substring(0, i) : s;
}
function sair(resumo, ret) { result(resumo); return ret; }

var atendimentoId = txt(params.id);
var quem = txt(usuario.username) || txt(usuario.id);
if (!atendimentoId || !quem) {
  log('aniversario: navegação sem atendimento ou sem usuário', 'warning');
  return sair({ aniversario: false, pulado: 'sem_contexto' }, { ok: true, aniversario: false, pulado: 'sem_contexto' });
}

// 1) atendimento → paciente
var ra = call('buscar_atendimento', { id: atendimentoId });
var at = unwrap(ra);
if (!at) {
  log('aniversario: FALHA ao ler o atendimento (HTTP ' + ((ra && ra.status_code) || '?') + ')', 'warning');
  return sair({ aniversario: null, acao_bloqueada: true, etapa: 'buscar_atendimento', http: (ra && ra.status_code) || null },
              { ok: false, erro: 'buscar_atendimento' });
}
var clienteId = txt(at.cliente_id) || txt(at.cliente && at.cliente.id);
if (!clienteId) {
  return sair({ aniversario: false, pulado: 'sem_paciente' }, { ok: true, aniversario: false, pulado: 'sem_paciente' });
}

// 2) paciente → data de nascimento
var rc = call('buscar_cliente', { cliente_id: clienteId });
var cli = unwrap(rc);
if (!cli) {
  log('aniversario: FALHA ao ler o paciente (HTTP ' + ((rc && rc.status_code) || '?') + ')', 'warning');
  return sair({ aniversario: null, acao_bloqueada: true, etapa: 'buscar_cliente', http: (rc && rc.status_code) || null },
              { ok: false, erro: 'buscar_cliente' });
}
var nasc = /^(\d{4})-(\d{2})-(\d{2})/.exec(txt(cli.data_nascimento));
if (!nasc) {
  return sair({ aniversario: false, pulado: 'sem_data_nascimento' }, { ok: true, aniversario: false });
}

// 3) é hoje? (fuso da clínica)
var local = new Date(Date.now() + offsetMin(knob(cfg.tz_offset, '-03:00')) * 60000);
var ano = local.getUTCFullYear();
var hoje = pad(local.getUTCMonth() + 1) + '-' + pad(local.getUTCDate());
var diaNasc = nasc[2] + '-' + nasc[3];
var bissexto = (ano % 4 === 0 && ano % 100 !== 0) || ano % 400 === 0;
if (diaNasc === '02-29' && !bissexto) diaNasc = '02-28';
if (diaNasc !== hoje) {
  return sair({ aniversario: false }, { ok: true, aniversario: false });
}

// 4) peças na tela de quem abriu
var rota = { padrao: ROTA, params: { id: atendimentoId } };
var base = {
  type: 'diretiva_ui', kind: 'snippet',
  duracao: { tipo: 'rota_pai' }, persistencia: 'efemero',
  rota: rota, requer_permissoes: REQUER, alvo: { user_id: quem }
};
if (txt(ev.navegacao_id)) base.navegacao_id = txt(ev.navegacao_id);
function peca(extra) {
  var p = {};
  var k;
  for (k in base) p[k] = base[k];
  for (k in extra) p[k] = extra[k];
  return p;
}

var nome = primeiroNome(cli.nome) || 'paciente';
var mensagem = knob(cfg.mensagem, MSG_PADRAO).split('{nome}').join(nome);

var rs = call('emitir_snippet', peca({
  componente: 'selo',
  posicao: { espaco: 'cabecalho.selos' },
  estilo: { cor: '#db2777', icone: 'aniversario', variante: 'suave' },
  titulo: 'Aniversário hoje',
  ref: 'aniversario-selo:' + clienteId + ':' + quem
}));
var rk = call('emitir_snippet', peca({
  componente: 'cartao',
  posicao: { espaco: 'lateral.topo' },
  estilo: { cor: '#db2777', icone: 'presente', variante: 'suave', borda: 'fina' },
  titulo: 'Mensagem de aniversário',
  corpo: 'Hoje é o aniversário de **' + nome + '**. Mensagem pronta para mandar:\n\n> ' + mensagem,
  ref: 'aniversario-cartao:' + clienteId + ':' + quem
}));

var selo = !!(rs && rs.ok);
var cartao = !!(rk && rk.ok);
var resumo = { aniversario: true, selo: selo, cartao: cartao };
if (!selo || !cartao) {
  resumo.acao_bloqueada = true;
  resumo.etapa = 'emitir_snippet';
  resumo.http = (!selo ? (rs && rs.status_code) : (rk && rk.status_code)) || null;
  log('aniversario: FALHA ao mostrar ' + (!selo ? 'o selo' : 'o cartão') + ' (HTTP ' + (resumo.http || '?') + ')', 'warning');
}
return sair(resumo, { ok: selo && cartao, aniversario: true, selo: selo, cartao: cartao });
